function longestObstacleCourseAtEachPosition(obstacles) {
    const nums = [...obstacles];
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const ans = [];
    const tree = new BinaryIndexedTree(n);
    const search = (x) => {
        let [l, r] = [0, n];
        while (l < r) {
            const mid = (l + r) >> 1;
            if (nums[mid] >= x) {
                r = mid;
            }
            else {
                l = mid + 1;
            }
        }
        return l;
    };
    for (let k = 0; k < n; ++k) {
        const i = search(obstacles[k]) + 1;
        ans[k] = tree.query(i) + 1;
        tree.update(i, ans[k]);
    }
    return ans;
}

